package com.northstar.crm.service;import org.junit.jupiter.api.Test;import java.util.*;import static com.northstar.crm.domain.DomainTypes.*;import static org.junit.jupiter.api.Assertions.*;class WorkflowRulesTest {@Test void dealTransitionsAreExplicitAndTerminalLossIsTerminal(){assertEquals(Set.of(DealStage.QUALIFIED,DealStage.CLOSED_LOST),DealService.ALLOWED_TRANSITIONS.get(DealStage.LEAD));assertTrue(DealService.ALLOWED_TRANSITIONS.get(DealStage.CLOSED_LOST).isEmpty());assertFalse(DealService.ALLOWED_TRANSITIONS.get(DealStage.PROPOSAL).contains(DealStage.CLOSED_WON));}@Test void everyEscalationStateIsReachable(){var reached=EnumSet.of(EscalationStatus.OPEN);boolean changed;do{changed=false;for(var state:List.copyOf(reached))for(var next:EscalationService.ALLOWED_TRANSITIONS.get(state))changed|=reached.add(next);}while(changed);assertEquals(EnumSet.allOf(EscalationStatus.class),reached);}}
